const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Helper to evaluate EE objects as Promises
    const eeGet = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));

    // 1. Geometry & Time Definitions (near La Jolla coast, slightly offshore to avoid land)
    const center = ee.Geometry.Point([-117.35, 32.85]); // ~15 km offshore La Jolla
    const region = center.buffer(20000); // 20 km buffer
    const collId = 'NOAA/CDR/OISST/V2';

    // Helper to get daily (with fallback widen window) SST image and report size/window used
    async function getSSTImage(dateStr) {
      const start = ee.Date(dateStr);
      const end = start.advance(1, 'day');
      let col = ee.ImageCollection(collId).filterDate(start, end).select('sst');
      let size = await eeGet(col.size());
      let window = '1d';
      if (size === 0) {
        // Widen window ±1 day
        const wStart = start.advance(-1, 'day');
        const wEnd = end.advance(1, 'day');
        col = ee.ImageCollection(collId).filterDate(wStart, wEnd).select('sst');
        size = await eeGet(col.size());
        window = '3d';
      }
      if (size === 0) return { img: null, size: 0, window };
      // Use median in case widened window returns multiple images
      const img = col.median().set('window', window);
      return { img, size, window };
    }

    // 2. Data Acquisition & Checks
    const y2017 = await getSSTImage('2017-08-01');
    const y2018 = await getSSTImage('2018-08-01');

    console.log('Dataset: NOAA/CDR/OISST/V2');
    console.log(`2017 Images: ${y2017.size} (win: ${y2017.window})`);
    console.log(`2018 Images: ${y2018.size} (win: ${y2018.window})`);

    if (y2017.size === 0 || y2018.size === 0) {
      console.log('C1');
      return;
    }

    // 3. Processing: pixel counts (valid data) and mean SST
    async function stats(img) {
      const count = await eeGet(
        img.select('sst').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: 25000,
          maxPixels: 1e9,
        }).get('sst')
      );
      const mean = await eeGet(
        img.select('sst').reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: region,
          scale: 25000,
          maxPixels: 1e9,
        }).get('sst')
      );
      return { count: count || 0, mean };
    }

    const s17 = await stats(y2017.img);
    const s18 = await stats(y2018.img);

    if (s17.count === 0 || s18.count === 0) {
      console.log('No valid pixels after masking/region at chosen scale.');
      console.log('C2');
      return;
    }

    // 4. Validation & Final Calculation
    const validRange = (v) => v !== null && isFinite(v) && v > -5 && v < 45; // °C plausible SST
    if (!validRange(s17.mean) || !validRange(s18.mean)) {
      console.log(`Validation failed. 2017 mean: ${s17.mean}, 2018 mean: ${s18.mean}`);
      console.log('C3');
      return;
    }

    const diff = s18.mean - s17.mean;
    const fmt = (x) => (x === null || !isFinite(x) ? 'null' : x.toFixed(2));
    console.log(`2017 SST (°C): ${fmt(s17.mean)} | Valid px: ${s17.count}`);
    console.log(`2018 SST (°C): ${fmt(s18.mean)} | Valid px: ${s18.count}`);
    console.log(`Difference 2018 - 2017 (°C): ${fmt(diff)}`);

    // 5. Final Answer
    console.log(diff > 0 ? 'A' : 'B');
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
